package com.agrolink.controller;import com.agrolink.dto.payment.*;import com.agrolink.service.PaymentService;import jakarta.validation.Valid;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/payments") public class PaymentController{private final PaymentService s;public PaymentController(PaymentService s){this.s=s;}@PostMapping("/orders/{orderId}") public PaymentResponse initiate(Authentication a,@PathVariable Long orderId,@Valid @RequestBody PaymentRequest r){return s.initiate(a.getName(),orderId,r);}@PostMapping("/orders/{orderId}/confirm") public PaymentResponse confirm(Authentication a,@PathVariable Long orderId){return s.confirm(a.getName(),orderId);}}
